{"function": "() => {
    const articles = document.querySelectorAll('article');
    const winners = [];
    articles.forEach(article => {
        // find div that contains only year (maybe with quotes)
        const divs = article.querySelectorAll('div');
        let year = '';
        let country = '';
        for (let div of divs) {
            const text = div.textContent.trim();
            // check if text is a year (four digits)
            if (/^\d{4}$/.test(text)) {
                year = text;
            } else if (text && text !== year && !text.includes('\n')) {
                // might be country
                country = text;
            }
        }
        const nameElem = article.querySelector('h2');
        if (year && nameElem) {
            const name = nameElem.textContent.trim();
            // clean country: sometimes contains name again
            if (country.includes(name)) {
                // extract after newline
                const lines = country.split('\n');
                country = lines[lines.length - 1].trim();
            }
            winners.push({year, name, country});
        }
    });
    return winners;
}"}

